"""Primary-authored structured designs for the 36 duration-atlas cases."""

from __future__ import annotations

from typing import Any


FAMILY_QUESTIONS = {
    "repository-trace": "How long does evidence-backed repository tracing take as the required path crosses more contracts and runtimes?",
    "code-review": "How do diff surface and hidden lifecycle interactions affect review time and seeded-finding quality?",
    "failing-test-diagnosis": "How do reproduction cost and failure distance affect time to a defensible root cause and regression strategy?",
    "bounded-implementation": "How do edit/test coupling and validation depth affect time to a contract-valid patch?",
    "refactor-migration": "How do caller discovery, compatibility, and rollback obligations affect a behavior-preserving migration?",
    "test-design": "How do mutation surface and lifecycle nondeterminism affect time to a test suite that rejects known-bad behavior?",
    "documentation-runbook": "How do source-of-truth breadth and executable recovery obligations affect accurate documentation time?",
    "architecture-design": "How do ambiguity, constraint breadth, and counterexamples affect time and coverage of a design decision?",
    "security-isolation": "How do adversarial combinations and environment boundaries affect time to identify and prove isolation failures?",
    "performance-resource": "How do instrumentation breadth and measurement noise affect time to a reproducible bottleneck diagnosis?",
    "devcontainer-operations": "How do lifecycle boundaries, persistent state, and recovery obligations affect operational change time?",
    "evidence-synthesis": "How do claim count, contradiction, and evidence quality affect time to a supported decision record?",
}


def C(
    *,
    case_id: str,
    family: str,
    size: str,
    profile_id: str,
    scenario: str,
    descriptors: tuple[str, str, str, list[str], str, str, str],
    stack: list[str],
    files: list[tuple[str, str, str]],
    seed: str,
    work_path: list[str],
    task: str,
    requirements: list[str],
    public_checks: list[str],
    hidden: list[tuple[str, str, str]],
    mutants: list[str],
    known_good: str,
    rubric_boundary: str,
    collaboration: list[str],
    analysis: list[str],
    capsule_path: str,
    ambiguity: str = "exact",
    oracle: str = "deterministic",
    decomposability: str = "serial",
    artifact_type: str = "answer",
    risk: str = "low",
    lane: str | None = None,
    environment: str = "local-tool",
    knowledge: str = "repository-contained",
    timeout: str | None = None,
    depth_sensitive: bool = False,
    non_goals: list[str] | None = None,
    allowed: list[str] | None = None,
    implementation: list[str] | None = None,
    fixture_note: str | None = None,
    task_note: str | None = None,
    oracle_note: str | None = None,
    definition_of_done_extra: list[str] | None = None,
) -> dict[str, Any]:
    context, artifact, coupling, validation, setup, distance, state = descriptors
    chosen_timeout = timeout or {"S": "20 minutes", "M": "45 minutes", "L": "90 minutes"}[size]
    chosen_lane = lane or {
        "repository-trace": "read",
        "code-review": "read",
        "failing-test-diagnosis": "read",
        "bounded-implementation": "write",
        "refactor-migration": "write",
        "test-design": "write",
        "documentation-runbook": "write",
        "architecture-design": "read",
        "security-isolation": "isolated",
        "performance-resource": "isolated",
        "devcontainer-operations": "write",
        "evidence-synthesis": "read",
    }[family]
    execution = [
        "C0/fresh/automatic-permissionでCodex Sol、Grok 4.6、再認証済みClaudeのprovider seriesを分離して観測する。",
        "各providerでnormal-depth候補のmediumとdeep候補のxhighを同一case revisionへ実行し、順序を観測blockごとに反転する。",
        "unsupported/rejected settingは短いcapability probeで確定し、task duration sampleへ混ぜない。",
    ]
    if depth_sensitive:
        execution.append(
            "rubricがquality差を識別した後、Codexはhigh/max/ultra、GrokとClaudeはadvertisedかつapplied確認可能なhigh/max相当も同一identity blockへ追加する。"
        )
    else:
        execution.append(
            "mediumとxhighが同一qualityで時間だけ異なる場合は、このcaseだけを理由にさらに深いsettingを推奨せずraw curveとして残す。"
        )
    default_allowed = [
        "fixture内のsource、tests、docsを読み、repository-containedなlocal commandを実行する。",
        "taskで指定されたartifact pathだけを作成・変更する。",
        "一時fileはfixture内またはprocess-owned temporary directoryだけに作る。",
    ]
    default_implementation = [
        "recipeは`case_id/files/hidden/good/executable`の共通interfaceを満たし、stdlibだけで構成する。",
        "initial state、plausible negative mutant、private known-goodを同じsource contractから校正できるようにする。",
        "hidden check IDはこの設計と一致させ、criterionごとのpass/failを保持する。",
        "capsule digest、catalog descriptor、visible path allowlistを実体と一致させる。",
    ]
    return {
        "case_id": case_id,
        "family": family,
        "size": size,
        "profile_id": profile_id,
        "scenario": scenario,
        "measurement_question": FAMILY_QUESTIONS[family],
        "descriptors": {
            "context_surface": context,
            "artifact_surface": artifact,
            "coupling": coupling,
            "validation_depth": validation,
            "environment_setup": setup,
            "failure_distance": distance,
            "statefulness": state,
        },
        "ambiguity": ambiguity,
        "oracle": oracle,
        "decomposability": decomposability,
        "artifact_type": artifact_type,
        "risk": risk,
        "lane": chosen_lane,
        "environment": environment,
        "knowledge": knowledge,
        "stack": stack,
        "reveals": [
            "first contract-valid artifactとuser-resultまでの差。",
            "public validation、hidden quality score、offline scoringの時間境界。",
            f"{family}の{size} profileで、探索・生成・検証のどこが支配項になるか。",
        ],
        "non_goals": non_goals or [
            "provider/modelの総合rankingを作らない。",
            "この一件からfamily typical timeやmulti-agent routing ruleを作らない。",
            "fixture外の現行product behaviorを変更しない。",
        ],
        "files": [{"path": path, "role": role, "initial": initial} for path, role, initial in files],
        "seed": seed,
        "work_path": work_path,
        "known_good": known_good,
        "fixture_note": fixture_note,
        "task": task,
        "task_note": task_note,
        "requirements": requirements,
        "allowed": allowed or default_allowed,
        "public_checks": public_checks,
        "hidden": [{"id": item_id, "criterion": criterion, "signal": signal} for item_id, criterion, signal in hidden],
        "mutants": mutants,
        "rubric_boundary": rubric_boundary,
        "oracle_note": oracle_note,
        "execution": execution,
        "collaboration": collaboration,
        "timeout": chosen_timeout,
        "analysis": analysis,
        "capsule_path": capsule_path,
        "implementation": implementation or default_implementation,
        "definition_of_done": [
            "catalog fragmentとcase schemaがvalidateする。",
            "同一時刻で二回生成したfixtureのsnapshot inventory/digestが再現する。",
            "initial evaluatorがfailし、private known-goodがpublic/hidden全criterionをpassする。",
            "各negative mutantが意図したcriterionでrejectされるfocused testがある。",
            "network-disabled read-only isolated evaluatorで同じscoreが得られる。",
        ] + (definition_of_done_extra or []),
    }


